ull(R.Refund_MarketplaceFacilitatorTax_Principal,0) as Refund_MarketplaceFacilitatorTax_Principal ,ifnull(R.Refund_MarketplaceFacilitatorTax_Shipping,0) as Refund_MarketplaceFacilitatorTax_Shipping ,ifnull(R.Refund_MarketplaceFacilitatorTax_Other,0) as Refund_MarketplaceFacilitatorTax_Other ,ifnull(R.Refund_MarketplaceFacilitatorVat_Shipping,0) as Refund_MarketplaceFacilitatorVat_Shipping ,ifnull(R.Refund_MarketplaceFacilitatorVat_Principal,0)as Refund_MarketplaceFacilitatorVat_Principal ,S.GIFTWRAP ,S.GIFTWRAPTAX ,S.SHIPPINGCHARGE ,S.SHIPPINGTAX ,S.MARKETPLACEFACILITATORTAXPRINCIPAL ,S.MARKETPLACEFACILITATORTAXSHIPPING ,S.MARKETPLACEFACILITATORTAXOTHER ,S.MARKETPLACEFACILITATORVATSHIPPING ,S.MARKETPLACEFACILITATORVATPRINCIPAL ,S.FBAPERORDERFULFILLMENTFEE ,S.FBAWEIGHTBASEDFEE ,S.FIXEDCLOSINGFEE ,S.GIFTWRAPCHARGEBACK ,S.SHIPPINGCHARGEBACK ,S.VARIABLECLOSINGFEE ,ifnull(S.SALESTAXCOLLECTIONFEE,0) as SALESTAXCOLLECTIONFEE ,ifnull(S.GIFTWRAPCOMMISSION,0) as GIFTWRAPCOMMISSION ,ifnull(S.SHIPPINGHB,0) as SHIPPINGHB from Shipment S full outer join Refund R on S.AMAZONORDERID = R.AMAZONORDERID and lower(S.SELLERSKU) = lower(R.SELLERSKU) left join Orders O on lower(coalesce(S.SELLERSKU,R.SELLERSKU)) = lower(O.SKU) where MarketplaceName <> \'Amazon.com.mx\' order by POSTEDDATE desc;",
